package cn.sifangguan.hotelaios.finance;
import cn.sifangguan.hotelaios.shared.audit.AuditWriter;
import cn.sifangguan.hotelaios.shared.context.TenantPrincipal;
import cn.sifangguan.hotelaios.shared.db.TenantDatabaseContext;
import cn.sifangguan.hotelaios.shared.security.*;
import org.springframework.jdbc.core.namedparam.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;
import java.time.*;
import java.util.*;
import static cn.sifangguan.hotelaios.finance.FinanceV2Support.*;

/** Archive access is an additional gate, never a replacement for the live source's permissions. */
@Service @Transactional
public class FinanceArchiveService {
 private final NamedParameterJdbcTemplate jdbc;private final TenantDatabaseContext database;private final AccessPolicy access;private final AuditWriter audit;private final FinanceArchiveSources sources;
 public FinanceArchiveService(NamedParameterJdbcTemplate jdbc,TenantDatabaseContext database,AccessPolicy access,AuditWriter audit,FinanceArchiveSources sources){this.jdbc=jdbc;this.database=database;this.access=access;this.audit=audit;this.sources=sources;}
 private TenantPrincipal prepare(){access.requireAnyPermission("finance.archive.read","finance.archive.grant");var p=access.principal();database.apply(p.tenantId());return p;}
 private boolean grant(TenantPrincipal p){return p.hasPermission("*")||p.hasPermission("finance.archive.grant");}
 private static String array(Collection<?> values){return "{"+String.join(",",values.stream().map(Object::toString).toList())+"}";}
 public Map<String,Object> context(){var p=prepare();return Map.of("sourceTypes",FinanceArchiveSources.TYPES,"canGrant",grant(p),"maxGrantHours",72,"automaticDeletionEnabled",false,"companies",output(Map.of("items",jdbc.queryForList("select distinct c.id,c.name from finance_company c join finance_store_config s on s.tenant_id=c.tenant_id and s.company_id=c.id where c.tenant_id=:tenant and s.enabled and (:tenantScope or s.hotel_id in (:scopes)) order by c.name",base(p)))).get("items"),"originalsPolicy","批注与财务原件分离保存。调阅批准不授予其他门店、工资、税务或原件权限；原来源权限每次重新校验。","restoreStatus","NOT_VERIFIED_BY_ARCHIVE_UI","restoreGuide","数据库、finance-evidence及finance-business-evidence须配套备份并在隔离环境实际恢复核对；导出清单不是恢复成功证明。");}
 public Map<String,Object> preview(String type,UUID sourceId){prepare();return output(sources.resolve(type,sourceId));}
 public Map<String,Object> freeze(FinanceArchiveModels.Freeze in){var p=prepare();if(!in.restricted()&&!grant(p))throw bad("只有独立调阅管理员可创建范围内公开档案，默认应受限保存");var source=sources.resolve(in.sourceType(),in.sourceId());if(!in.expectedSourceVersion().equals(source.get("sourceVersion")))throw conflict("原单或凭证/原件版本已变化，请重新预览后归档");String hash=FinanceArchiveSources.canonicalHash(output(source));var b=base(p).addValue("id",in.requestId()).addValue("type",in.sourceType()).addValue("source",in.sourceId()).addValue("hash",hash);var old=jdbc.queryForList("select * from fac_archive where tenant_id=:tenant and id=:id",b);if(!old.isEmpty()){if(!hash.equals(old.getFirst().get("snapshot_hash"))||!in.title().equals(old.getFirst().get("title"))||in.restricted()!=Boolean.TRUE.equals(old.getFirst().get("restricted")))throw conflict("归档请求编号内容不一致");return detail(in.requestId());}
  b.addValue("hotels",array((Collection<?>)source.get("hotelIds"))).addValue("companies",array((Collection<?>)source.get("companyIds"))).addValue("version",in.expectedSourceVersion()).addValue("snapshot",json(output(source))).addValue("title",in.title()).addValue("restricted",in.restricted()).addValue("salary",source.get("sensitivePayroll"));
  jdbc.update("insert into fac_archive(id,tenant_id,source_type,source_id,hotel_ids,company_ids,source_version,snapshot_hash,snapshot,title,restricted,sensitive_payroll,created_by) values(:id,:tenant,:type,:source,cast(:hotels as uuid[]),cast(:companies as uuid[]),:version,:hash,cast(:snapshot as jsonb),:title,:restricted,:salary,:actor) on conflict(tenant_id,source_type,source_id,snapshot_hash) do nothing",b);UUID result=jdbc.queryForObject("select id from fac_archive where tenant_id=:tenant and source_type=:type and source_id=:source and snapshot_hash=:hash",b,UUID.class);log(p,result,"FROZEN",hash);return detail(result);
 }
 public Map<String,Object> list(String type,UUID source){var p=prepare();var b=base(p).addValue("type",Objects.toString(type,"")).addValue("source",source).addValue("salary",p.hasPermission("*")||p.hasPermission("finance.payroll"));var candidates=jdbc.queryForList("select * from fac_archive where tenant_id=:tenant and (:type='' or source_type=:type) and (cast(:source as uuid) is null or source_id=:source) and (:tenantScope or hotel_ids <@ array[:scopes]::uuid[]) and (:salary or not sensitive_payroll) order by created_at desc,id limit 200",b);var visible=new ArrayList<Map<String,Object>>();for(var row:candidates)if(authorized(row))visible.add(meta(row));return Map.of("items",visible,"windowLimit",200,"hasMoreCandidates",candidates.size()==200,"note","列表只展示当前原来源权限仍可读取的档案元数据，不表示已获受限内容调阅授权。");}
 private boolean authorized(Map<String,Object> row){try{scope(row);sources.resolve(row.get("source_type").toString(),id(row.get("source_id")));if(row.get("snapshot")!=null)sources.authorizeLinked(map(row.get("snapshot")));return true;}catch(AccessDeniedException denied){return false;}catch(ResponseStatusException denied){if(denied.getStatusCode().value()==403||denied.getStatusCode().value()==404)return false;throw denied;}}
 private Map<String,Object> load(UUID id,boolean lock){var p=prepare();var rows=jdbc.queryForList("select * from fac_archive where tenant_id=:tenant and id=:id"+(lock?" for update":""),base(p).addValue("id",id));if(rows.isEmpty())throw missing();var row=rows.getFirst();scope(row);sources.resolve(row.get("source_type").toString(),id(row.get("source_id")));sources.authorizeLinked(map(row.get("snapshot")));return row;}
 private void scope(Map<String,Object> row){if(Boolean.TRUE.equals(row.get("sensitive_payroll")))access.requirePermission("finance.payroll");try{for(Object h:(Object[])((java.sql.Array)row.get("hotel_ids")).getArray())access.requireOrgScope(id(h));}catch(java.sql.SQLException e){throw new IllegalStateException(e);}}
 private boolean readable(Map<String,Object> row){var p=access.principal();if(!Boolean.TRUE.equals(row.get("restricted"))||p.actorId().equals(id(row.get("created_by")))||grant(p))return true;return Boolean.TRUE.equals(jdbc.queryForObject("select exists(select 1 from fac_request where tenant_id=:tenant and archive_id=:id and applicant_id=:actor and status='APPROVED' and expires_at>now())",base(p).addValue("id",row.get("id")),Boolean.class));}
 private Map<String,Object> meta(Map<String,Object> row){var out=new LinkedHashMap<String,Object>();for(String key:List.of("id","source_type","source_id","source_version","snapshot_hash","title","restricted","sensitive_payroll","created_by","created_at"))out.put(key,row.get(key));out.put("canRead",readable(row));return output(out);}
 public Map<String,Object> detail(UUID id){var p=prepare();var row=load(id,false);if(!readable(row))throw new AccessDeniedException("受限财务档案尚未取得调阅批准，或限时授权已过期。请提交申请；组织、工资及原件权限不能借调阅绕过。");var snapshot=map(row.get("snapshot"));if(!FinanceArchiveSources.canonicalHash(snapshot).equals(row.get("snapshot_hash")))throw conflict("档案完整性校验不一致，请停止调阅并恢复备份");var result=meta(row);result.put("snapshot",snapshot);result.put("notes",output(Map.of("items",jdbc.queryForList("select n.id,n.body,n.created_by,n.created_at,u.display_name from fac_note n join user_account u on u.tenant_id=n.tenant_id and u.id=n.created_by where n.tenant_id=:tenant and archive_id=:id order by created_at,id",base(p).addValue("id",id)))).get("items"));result.put("versions",list(row.get("source_type").toString(),id(row.get("source_id"))).get("items"));log(p,id,"VIEW",row.get("snapshot_hash").toString());return result;}
 public Map<String,Object> note(UUID id,FinanceArchiveModels.Note in){var p=prepare();detail(id);var b=base(p).addValue("id",in.requestId()).addValue("archive",id).addValue("body",in.body());var old=jdbc.queryForList("select archive_id,body,created_by from fac_note where tenant_id=:tenant and id=:id",b);if(!old.isEmpty()){var v=old.getFirst();if(!id.equals(v.get("archive_id"))||!in.body().equals(v.get("body"))||!p.actorId().equals(v.get("created_by")))throw conflict("批注请求编号已占用");return detail(id);}jdbc.update("insert into fac_note(id,tenant_id,archive_id,body,created_by) values(:id,:tenant,:archive,:body,:actor)",b);log(p,id,"ANNOTATE",in.requestId().toString());return detail(id);}
 public Map<String,Object> request(UUID id,FinanceArchiveModels.Request in){var p=prepare();load(id,false);var b=base(p).addValue("id",in.requestId()).addValue("archive",id).addValue("reason",in.reason()).addValue("hours",in.hours());var old=jdbc.queryForList("select * from fac_request where tenant_id=:tenant and id=:id",b);if(!old.isEmpty()){var o=old.getFirst();if(!id.equals(o.get("archive_id"))||!p.actorId().equals(o.get("applicant_id"))||!in.reason().equals(o.get("reason"))||in.hours()!=((Number)o.get("requested_hours")).intValue())throw conflict("调阅请求编号内容变化");return output(o);}if(jdbc.queryForObject("select count(*) from fac_request where tenant_id=:tenant and archive_id=:archive and applicant_id=:actor and status='PENDING'",b,Integer.class)>0)throw conflict("已有待审核调阅申请，请等待处理");jdbc.update("insert into fac_request(id,tenant_id,archive_id,applicant_id,reason,requested_hours) values(:id,:tenant,:archive,:actor,:reason,:hours)",b);log(p,id,"REQUEST",in.requestId().toString());return output(jdbc.queryForMap("select * from fac_request where tenant_id=:tenant and id=:id",b));}
 public Map<String,Object> requests(){var p=prepare();var results=new ArrayList<Map<String,Object>>();for(var r:jdbc.queryForList("select r.*,a.source_type,a.source_id,a.hotel_ids,a.sensitive_payroll,a.title,a.snapshot from fac_request r join fac_archive a on a.tenant_id=r.tenant_id and a.id=r.archive_id where r.tenant_id=:tenant and (:manager or r.applicant_id=:actor) and (:tenantScope or a.hotel_ids <@ array[:scopes]::uuid[]) order by r.created_at desc limit 200",base(p).addValue("manager",grant(p))))if(authorized(r)){r.put("history",jdbc.queryForList("select from_status,to_status,note,expires_at,reviewer_id,request_version,created_at from fac_decision where tenant_id=:tenant and request_id=:id order by request_version",base(p).addValue("id",r.get("id"))));r.remove("hotel_ids");r.remove("snapshot");results.add(output(r));}return Map.of("items",results);}
 public Map<String,Object> decide(UUID request,FinanceArchiveModels.Decision in,boolean revoke){var p=prepare();access.requirePermission("finance.archive.grant");var b=base(p).addValue("id",request);var list=jdbc.queryForList("select * from fac_request where tenant_id=:tenant and id=:id for update",b);if(list.isEmpty())throw missing();var row=list.getFirst();version(row,in.expectedVersion());load(id(row.get("archive_id")),false);if(p.actorId().equals(id(row.get("applicant_id"))))throw new AccessDeniedException("不能审核或管理本人的调阅授权");if(revoke&&!row.get("status").equals("APPROVED")||!revoke&&!row.get("status").equals("PENDING"))throw conflict("调阅申请不在可处理环节");String status=revoke?"REVOKED":in.approve()?"APPROVED":"REJECTED";b.addValue("status",status).addValue("note",in.note()).addValue("hours",row.get("requested_hours"));jdbc.update("update fac_request set status=:status,reviewer_id=:actor,decision_note=:note,expires_at=case when :status='APPROVED' then now()+make_interval(hours=>:hours) else expires_at end,reviewed_at=now(),version=version+1 where tenant_id=:tenant and id=:id",b);var decided=jdbc.queryForMap("select * from fac_request where tenant_id=:tenant and id=:id",b);jdbc.update("insert into fac_decision(id,tenant_id,request_id,from_status,to_status,note,expires_at,reviewer_id,request_version) values(:decision,:tenant,:id,:before,:status,:note,:expires,:actor,:version)",b.addValue("decision",UUID.randomUUID()).addValue("before",row.get("status")).addValue("expires",decided.get("expires_at")).addValue("version",decided.get("version")));log(p,id(row.get("archive_id")),status,request.toString());return output(decided);}
 public Map<String,Object> export(UUID id){var data=detail(id);log(access.principal(),id,"EXPORT",data.get("snapshotHash").toString());return data;}
 public FinanceAccountingService.ExportFile exportReport(UUID id,String expectedReportVersion,String reportType,String format){var archived=detail(id);var snapshot=map(archived.get("snapshot"));if(!"BOOK_REPORT".equals(snapshot.get("sourceType")))throw bad("该档案不是独立已关账三表，不能以其他报表替代");if(!Set.of("INCOME_STATEMENT","BALANCE_SHEET","CASH_FLOW").contains(reportType))throw bad("请选择本档案冻结利润表、资产负债表或现金流量表");var report=map(map(snapshot.get("payload")).get("report"));String version=Objects.toString(report.get("reportVersion"),"");if(version.isBlank()||!version.equals(expectedReportVersion))throw conflict("档案报表版本与所选冻结版本不一致，未导出当前其他报表");byte[] bytes=FinanceAccountingExportRenderer.render(report,format,reportType);log(access.principal(),id,"FROZEN_REPORT_EXPORTED",version+":"+reportType+":"+format);return new FinanceAccountingService.ExportFile("财务档案三表-"+report.get("month")+"-"+reportType+"."+format,format.equals("xlsx")?"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet":"application/pdf",bytes,version);}
 public Map<String,Object> recordOriginal(UUID id,UUID attachment){var p=prepare();var row=load(id,false);if(!readable(row))throw new AccessDeniedException("调阅批准缺失或已过期");var snapshot=map(row.get("snapshot"));var linked=rows(snapshot.get("graph")).stream().filter(n->"ORIGINAL".equals(n.get("type"))&&attachment.toString().equals(n.get("id").toString())).findFirst();if(linked.isEmpty())throw missing();var original=linked.get();log(p,id,"ORIGINAL_REQUESTED",attachment.toString());return Map.of("sourceType",original.get("sourceType"),"sourceId",original.get("sourceId"));}
 public void originalRead(UUID id,UUID attachment){var p=prepare();var row=load(id,false);if(!readable(row))throw new AccessDeniedException("调阅授权已结束，请重新申请");log(p,id,"ORIGINAL_READ",attachment.toString());}
 public Map<String,Object> policies(){var p=prepare();return output(Map.of("items",jdbc.queryForList("select r.* from fac_retention r where r.tenant_id=:tenant and exists(select 1 from finance_store_config c where c.tenant_id=r.tenant_id and c.company_id=r.company_id and (:tenantScope or c.hotel_id in (:scopes))) order by r.created_at desc",base(p)),"automaticDeletionEnabled",false));}
 public Map<String,Object> policy(FinanceArchiveModels.Retention in){var p=prepare();access.requirePermission("finance.archive.grant");company(in.companyId());var b=base(p).addValue("id",in.requestId()).addValue("company",in.companyId()).addValue("years",in.years()).addValue("hold",in.legalHold()).addValue("reason",in.reason());if(jdbc.queryForObject("select count(*) from fac_retention where tenant_id=:tenant and id=:id",b,Integer.class)>0)throw conflict("保存策略请求编号已存在，请查看原版本");jdbc.update("insert into fac_retention(id,tenant_id,company_id,years,legal_hold,reason,created_by) values(:id,:tenant,:company,:years,:hold,:reason,:actor)",b);return policies();}
 private void company(UUID company){var p=access.principal();var scopes=jdbc.queryForList("select hotel_id from finance_store_config where tenant_id=:tenant and company_id=:company and enabled",base(p).addValue("company",company));if(scopes.isEmpty())throw bad("该法人没有有效财务组织配置");for(var scope:scopes)access.requireOrgScope(id(scope.get("hotel_id")));}
 public Map<String,Object> publishPolicy(UUID id){var p=prepare();access.requirePermission("finance.archive.grant");var b=base(p).addValue("id",id);var rows=jdbc.queryForList("select * from fac_retention where tenant_id=:tenant and id=:id for update",b);if(rows.isEmpty())throw missing();var row=rows.getFirst();company(id(row.get("company_id")));if(p.actorId().equals(id(row.get("created_by"))))throw new AccessDeniedException("保存策略须其他授权账号独立发布");if(!row.get("status").equals("DRAFT"))throw conflict("策略已发布，不能覆盖历史");jdbc.update("update fac_retention set status='PUBLISHED',published_by=:actor,published_at=now() where tenant_id=:tenant and id=:id",b);audit.record("FINANCE_RETENTION_PUBLISHED","FINANCE_ARCHIVE_POLICY",id,"{}");return policies();}
 public Map<String,Object> manifest(){var p=prepare();var records=rows(list(null,null).get("items"));audit.record("FINANCE_ARCHIVE_MANIFEST_EXPORTED","FINANCE_ARCHIVE",null,json(Map.of("count",records.size())));return Map.of("kind","AUTHORIZED_ARCHIVE_MANIFEST_NOT_BACKUP_OR_RESTORE_PROOF","generatedAt",Instant.now().toString(),"archives",records,"requiresPairedDatabaseAndOriginalBlobs",true,"restoreVerified",false,"windowLimit",200);}
 private void log(TenantPrincipal p,UUID id,String action,String reference){jdbc.update("insert into fac_access(id,tenant_id,archive_id,actor_id,action,reference) values(:event,:tenant,:id,:actor,:action,:reference)",base(p).addValue("event",UUID.randomUUID()).addValue("id",id).addValue("action",action).addValue("reference",reference));audit.record("FINANCE_ARCHIVE_"+action,"FINANCE_ARCHIVE",id,json(Map.of("reference",reference)));}
}
